"""Soulash 2의 문서화된 참조 필드를 실제 정의와 연결하여 별도 판정을 남긴다.

기존 인벤토리·원본·번역 후보를 바꾸지 않는다. ID가 일치하는 것만으로는
분류하지 않고, 필드 구조와 동봉 모딩 문서가 참조 용도를 설명해야 한다.
"""

import argparse
from collections import Counter, defaultdict
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import re
import sys


ROOT = Path(__file__).resolve().parents[1]
BUILD = "0.10.4.0.1_20261029"
CORE = "data/mods/core_2/"
DOC = "data/docs/index.html"

# 문서 근거는 실제 동봉 문서에서 구문을 찾아 행과 내용 지문을 기록한다.
DOC_ANCHORS = {
    "map_ids": ("<strong>ids</strong> - autogenerated Map IDs", 0, 2),
    "map_reference": ("Make sure to remove all references to that map", 0, 3),
    "spawn_ids": ("<strong>entities</strong> - autogenerated entity ids", 0, 2),
    "reward_entity": ("<strong>entity</strong> - the chest in here is the Entity ID", 0, 1),
    "building_occupation": ("<strong>occupation</strong> - index of entity", 0, 1),
    "building_race": ("<strong>race</strong> - which race can build this building", 0, 0),
    "entity_identity": ("Soulash 2 uses two identifiers for its entities", 0, 3),
    "entity_dialogue": ("<strong>Dialogues</strong> - optional dialogue select", 0, 0),
    "dialogue_id": ("<strong>id</strong> - unique id of this dialogue", 0, 0),
    "dialogue_editor_name": ("<strong>name</strong> - name of the dialogue", 0, 2),
    "entity_milestone": ("<strong>innate</strong> - boolean", 0, 0),
    "milestone_id": ("<strong>id</strong> - unique id of your milestone", 0, 0),
    "recipe_reward": ("<strong>rewards.recipe</strong> - a new recipe", 0, 1),
    "ability_reward": ("<strong>ability</strong> a new ability provided, use ID", 0, 0),
    "passive_reward": ("<strong>passive</strong> - a new passive provided", 0, 0),
    "production_reward": ("<strong>production_action</strong> - a new action provided", 0, 1),
    "amplifier_reward": ("<strong>amplifier</strong> - a new amplifier", 0, 2),
    "milestone_skill": ("<strong>skill_id</strong> - this an unique id of a skill", 0, 0),
    "ability_skill": ("<strong>Skill</strong> - what skill is bound with this ability", 0, 1),
    "ability_user": ("<strong>AbilityUser</strong> - in Soulash 2", 0, 2),
    "usable_ability": ("<strong>Usable</strong> - Usable items provide abilities or recipes", 0, 3),
    "entity_tags": ("<strong>Tags</strong> - Tags are recommended", 0, 1),
    "character_tags": ("<strong>tags</strong> - you can find examples of tags", 0, 1),
    "random_resource": ("<strong>Random resource</strong> - Random resource component", 0, 3),
    "internal_scenario_name": ("<strong>internal_name</strong>- internal name is for you", 0, 2),
    "description_sentinel": ("description generator, write <em>Placeholder</em>", -1, 1),
}


def rule(key, group, pattern, target, docs, reason, component=None):
    return {"id": key, "group": group, "pattern": pattern, "target": target,
            "docs": docs, "reason": reason, "component": component}


RULES = [
    rule("location_map_ids", "locations.json", r"/special/\*/scenarios/\*/building_maps/\*/ids/\*", "maps", ["map_ids", "map_reference"], "맵 생성 목록의 ids 배열은 .smap 첫 구분자 앞 지도 ID를 참조"),
    rule("location_spawn_entities", "locations.json", r"/special/\*/scenarios/\*/spawns/\*/entities/\*", "entities", ["spawn_ids", "entity_identity"], "위치 생성 spawns.entities 배열의 엔티티 템플릿 ID"),
    rule("location_reward_entity", "locations.json", r"/special/\*/scenarios/\*/rewards/\*/entity", "entities", ["reward_entity", "entity_identity"], "위치 보상 객체의 엔티티 템플릿 ID"),
    rule("building_occupation", "buildings", r"/occupation", "entities", ["building_occupation", "entity_identity"], "건물에서 일할 NPC로 바꿀 엔티티 템플릿 ID"),
    rule("building_race", "buildings", r"/race", "races", ["building_race"], "건물을 지을 종족의 character.json races ID"),
    rule("entity_milestones", "entities", r"/skills/milestones/\*", "milestones", ["entity_milestone", "milestone_id"], "엔티티에 부여하는 마일스톤 목록: skills.milestones 구조와 정의 ID", "skills"),
    rule("entity_dialogues", "entities", r"/dialogues/\*", "dialogues", ["entity_dialogue", "dialogue_id"], "별도 정의된 dialogue를 선택하는 엔티티 dialogues 구성요소", "dialogues"),
    rule("milestone_skill", "milestones", r"/skill_id", "skills", ["milestone_skill"], "마일스톤 소속 기술의 skills.json ID"),
    rule("milestone_recipe", "milestones", r"/rewards/\*/recipe", "entities", ["recipe_reward", "entity_identity"], "보상으로 제작할 수 있게 되는 엔티티 템플릿 ID"),
    rule("milestone_ability", "milestones", r"/rewards/\*/ability", "abilities", ["ability_reward"], "보상 능력의 정의 ID"),
    rule("milestone_passive", "milestones", r"/rewards/\*/passive", "passives", ["passive_reward"], "보상 지속 효과의 passives.json ID"),
    rule("milestone_production", "milestones", r"/rewards/\*/production_action", "production_actions", ["production_reward"], "보상 생산 행동의 character.json production_actions ID"),
    rule("milestone_amplifier", "milestones", r"/rewards/\*/amplifier", "ability_amplifiers", ["amplifier_reward"], "보상 강화 요소의 ability_amplifiers.json ID"),
    rule("ability_skill", "abilities", r"/skill", "skills", ["ability_skill", "milestone_skill"], "능력에 연결하여 경험치를 받을 기술의 정의 ID"),
    rule("entity_abilities", "entities", r"/ability_user/\*", "abilities", ["ability_user", "ability_reward"], "AbilityUser 구성요소가 사용하도록 부여하는 능력 ID", "ability_user"),
    rule("usable_ability", "entities", r"/usable/ability", "abilities", ["usable_ability", "ability_reward"], "Usable 구성요소로 아이템이 제공하는 능력의 ID", "usable"),
    rule("entity_tags", "entities", r"/tags/\*", "tags", ["entity_tags", "character_tags"], "엔티티에 부여하는 태그 선택값: character.json tags ID", "tags"),
    rule("random_entities", "entities", r"/random_resource/entity/\*", "entities", ["random_resource", "entity_identity"], "Random resource 구성요소가 생성하는 엔티티 ID", "random_resource"),
]


def digest(path):
    result = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            result.update(chunk)
    return result.hexdigest()


def object_no_duplicates(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("중복 키: " + key)
        result[key] = value
    return result


def json_load(path):
    return json.loads(path.read_text(encoding="utf-8-sig"), object_pairs_hook=object_no_duplicates)


def canonical_id(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, str)):
        return str(value)
    return None


def emit(stream, row):
    stream.write(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n")


def resolve_reference(row, selected, definitions, document):
    if selected.get("component") and selected["component"] not in document.get("components", []):
        return None, "component_not_declared"
    key = canonical_id(row["source"])
    targets = definitions[selected["target"]].get(key, [])
    if not targets:
        return None, "definition_missing"
    if len(targets) != 1:
        return None, "definition_ambiguous"
    return targets[0], None


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--build-id", default=BUILD)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    source = ROOT / "source_original/SOULASH_2" / args.build_id
    evidence = ROOT / "extracted_private/SOULASH_2" / args.build_id
    output = (args.output or evidence).resolve()
    if not output.is_relative_to(ROOT / "extracted_private"):
        raise SystemExit("출력은 extracted_private 아래여야 합니다.")
    filenames = ["classification_reference_overlay.jsonl", "classification_reference_unresolved.jsonl", "classification_reference_definitions.jsonl", "classification_reference_rules.json", "classification_display_hints.jsonl", "classification_reference_summary.json"]
    if any((output / name).exists() for name in filenames):
        raise SystemExit("기존 참조 조사 결과를 덮어쓰지 않습니다. 새 --output 경로를 지정하세요.")
    output.mkdir(parents=True, exist_ok=True)
    manifest_path = evidence / "baseline_manifest.json"
    inventory_path = evidence / "json_strings.jsonl"
    manifest = json_load(manifest_path)
    expected = {item["path"]: item for item in manifest["files"]}
    checked, documents = set(), {}
    started = datetime.now(timezone.utc).isoformat()

    def verified(relative):
        path = source / relative
        if relative not in checked:
            if relative not in expected or not path.is_file() or digest(path) != expected[relative]["sha256"]:
                raise ValueError("고정 기준선과 파일 불일치: " + relative)
            checked.add(relative)
        return path

    def document(relative):
        if relative not in documents:
            documents[relative] = json_load(verified(relative))
        return documents[relative]

    doc_path = verified(DOC)
    doc_lines = doc_path.read_text(encoding="utf-8-sig").splitlines()
    doc_evidence = {}
    for key, (phrase, before, after) in DOC_ANCHORS.items():
        matches = [index for index, line in enumerate(doc_lines) if phrase in line]
        if not matches:
            raise ValueError("문서 근거를 찾지 못했습니다: " + key)
        index = matches[0]
        start, end = index + before, index + after
        doc_evidence[key] = {"file": DOC, "sha256": expected[DOC]["sha256"], "line_start": start + 1, "line_end": end + 1, "text": "\n".join(doc_lines[start:end + 1]), "matched_occurrences": len(matches)}
    definitions = defaultdict(lambda: defaultdict(list))

    def add_definition(namespace, value, relative, field_path):
        key = canonical_id(value)
        if key is None:
            raise ValueError("정의의 ID 형식 확인 필요: " + relative + field_path)
        definitions[namespace][key].append({"namespace": namespace, "id": value, "canonical_id": key, "file": relative, "field_path": field_path, "file_sha256": expected[relative]["sha256"]})

    for namespace in ["entities", "abilities", "milestones"]:
        for path in sorted((source / CORE / namespace).rglob("*.json")):
            relative = path.relative_to(source).as_posix()
            obj = document(relative)
            add_definition(namespace, obj["id"], relative, "/id")
    for namespace in ["dialogues", "skills", "passives", "ability_amplifiers"]:
        relative = CORE + namespace + ".json"
        for index, obj in enumerate(document(relative)):
            add_definition(namespace, obj["id"], relative, f"/{index}/id")
    relative = CORE + "character.json"
    for namespace in ["races", "tags", "production_actions"]:
        for index, obj in enumerate(document(relative)[namespace]):
            add_definition(namespace, obj["id"], relative, f"/{namespace}/{index}/id")
    for path in sorted((source / CORE / "building_maps").glob("*.smap")):
        relative = path.relative_to(source).as_posix()
        raw = verified(relative).read_bytes()
        value = raw.decode("utf-8-sig").split("|", 1)[0]
        add_definition("maps", value, relative, "/header/0")
    counts, rule_counts, unresolved_reasons, hints = Counter(), Counter(), Counter(), Counter()
    locations_seen = set()
    with (output / filenames[0]).open("w", encoding="utf-8", newline="\n") as overlay, (output / filenames[1]).open("w", encoding="utf-8", newline="\n") as unresolved, (output / filenames[4]).open("w", encoding="utf-8", newline="\n") as display:
        for line in inventory_path.open(encoding="utf-8"):
            row = json.loads(line)
            if row["role"] != "primary_english":
                continue
            if row["source_file_sha256"] != expected[row["file"]]["sha256"]:
                raise ValueError("인벤토리 출처 내용 지문 불일치: " + row["file"])
            group = row["file"][len(CORE):].split("/")[0]
            is_sentinel = group == "entities" and row["field_path"] == "/description" and row["source"] == "Placeholder"
            if row["classification"] != "UNKNOWN" and not is_sentinel:
                continue
            if row["location_id"] in locations_seen:
                raise ValueError("입력 위치 ID 중복: " + row["location_id"])
            locations_seen.add(row["location_id"])
            counts["input_unknown" if not is_sentinel else "input_sentinel"] += 1
            base = {key: row[key] for key in ["location_id", "file", "field_path", "field_pattern", "source", "source_file_sha256", "source_value_sha256"]}
            base["previous_classification"] = row["classification"]
            base["runtime_observed"] = False
            selected = next((item for item in RULES if item["group"] == group and re.fullmatch(item["pattern"], row["field_pattern"])), None)
            if is_sentinel:
                emit(overlay, {**base, "classification": "INTERNAL", "rule_id": "description_generator_sentinel", "reason": "동봉 문서가 명시한 설명 생성기 활성화 예약값", "evidence_kind": "documented_reserved_value", "document_evidence": [doc_evidence["description_sentinel"]]})
                counts["sentinel_corrections"] += 1
                continue
            if selected:
                target, failure = resolve_reference(row, selected, definitions, document(row["file"]))
                if target:
                    emit(overlay, {**base, "classification": "INTERNAL", "rule_id": selected["id"], "reason": selected["reason"], "evidence_kind": "documented_field_and_resolved_definition", "target_definition": target, "document_evidence": [doc_evidence[key] for key in selected["docs"]], "component_required": selected["component"]})
                    counts["resolved_internal"] += 1
                    rule_counts[selected["id"]] += 1
                    continue
                reason = failure
            else:
                reason = "no_documented_reference_rule"
            emit(unresolved, {**base, "classification": "UNKNOWN", "reason": reason, "attempted_rule": selected["id"] if selected else None, "target_namespace": selected["target"] if selected else None})
            counts["remaining_unknown"] += 1
            unresolved_reasons[reason] += 1
            if group == "dialogues.json" and re.fullmatch(r"/\*/name", row["field_pattern"]):
                emit(display, {**base, "classification": "UNKNOWN", "hint": "동봉 문서가 Editor 표시명이라고 명시. 내부 키로 제외 금지; 번역 분류는 별도 검토", "document_evidence": [doc_evidence["dialogue_editor_name"]]})
                hints["dialogue_editor_name"] += 1
            if group == "locations.json" and row["field_pattern"].endswith("/internal_name"):
                emit(display, {**base, "classification": "UNKNOWN", "hint": "문서는 게임 실행에 미사용인 편집용 이름이라고 설명. 요청에 따라 UNKNOWN 유지", "document_evidence": [doc_evidence["internal_scenario_name"]]})
                hints["scenario_internal_name"] += 1
    with (output / filenames[2]).open("w", encoding="utf-8", newline="\n") as stream:
        for namespace, by_id in sorted(definitions.items()):
            for key, matches in sorted(by_id.items()):
                emit(stream, {"namespace": namespace, "canonical_id": key, "count": len(matches), "definitions": matches})
    (output / filenames[3]).write_text(json.dumps({"rules": RULES, "documentation": doc_evidence}, ensure_ascii=False, indent=2), encoding="utf-8")
    assert counts["input_unknown"] == counts["resolved_internal"] + counts["remaining_unknown"]
    summary = {"game_id": "SOULASH_2", "build_id": args.build_id, "check_id": "G2_REFERENCE_OVERLAY_V1", "status": "PASS", "scope": "영어 JSON UNKNOWN 중 문서화된 참조 필드의 정의 연결 및 별도 판정 생성", "g2_status": "NOT_RUN", "g2_reason": "남은 UNKNOWN·중복 키 로더 해석·코드·미디어·실행 검증 미완료", "started": started, "finished": datetime.now(timezone.utc).isoformat(), "command": sys.argv, "python_version": sys.version, "tool_sha256": digest(Path(__file__)), "baseline_manifest_sha256": digest(manifest_path), "inventory_sha256": digest(inventory_path), "checked_source_files": len(checked), "counts": counts, "rule_counts": rule_counts, "unresolved_reasons": unresolved_reasons, "display_hints": hints, "definition_counts": {ns: {"distinct_ids": len(by_id), "ambiguous_ids": sum(len(items) != 1 for items in by_id.values())} for ns, by_id in definitions.items()}, "output_files": {name: digest(output / name) for name in filenames[:-1]}, "unchanged": ["기존 인벤토리와 번역 후보", "원본 자산", "name/internal_name/레이어의 UNKNOWN", "기존 중복 키 추출 오류 상태"], "limitations": ["정적 문서와 파일 구조의 근거이며 실행 관찰 아님", "미해결·중복 정의는 INTERNAL로 바꾸지 않음", "지도 이름과 지도 ID를 구별하며 이름 자체는 처리하지 않음", "모든 JSON 키의 별도 UNKNOWN 목록은 변경하지 않음"]}
    (output / filenames[5]).write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding="utf-8")
    print(json.dumps({"counts": counts, "rule_counts": rule_counts, "unresolved_reasons": unresolved_reasons, "display_hints": hints}, ensure_ascii=False))


if __name__ == "__main__":
    main()
